def copy_discounts(apps, schema_editor):
    """One EnrollmentDiscount per enrollment that had a discount. A stored
    percentage with no discount type (old seeds) becomes a custom discount."""
    Enrollment = apps.get_model('enrollments', 'Enrollment')
    EnrollmentDiscount = apps.get_model('enrollments', 'EnrollmentDiscount')
    discounts = []
    for enrollment in Enrollment.objects.all():
        if not enrollment.discount_id and not enrollment.discount_percent:
            continue
        if enrollment.discount_id:
            discounts.append(EnrollmentDiscount(
                enrollment=enrollment,
                discount_type_id=enrollment.discount_id,
                percentage=enrollment.discount_percent or Decimal(0),
            ))
        else:
            discounts.append(EnrollmentDiscount(
                enrollment=enrollment,
                percentage=enrollment.discount_percent,
                observation='Desconto registrado antes dos descontos múltiplos',
            ))
    EnrollmentDiscount.objects.bulk_create(discounts)


